"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["75902"],{63370(e){e.exports=JSON.parse('{"id":"FIN-431","slug":"maturity-date","term":"Maturity Date","also_known_as":[],"difficulty":"Beginner","definition":"The maturity date is the date on which a bond, loan or other financial contract ends and the final payment is due, such as the repayment of a bond\'s face value.","explanation":["Every bond has a maturity date. On that date, the issuer repays the face value to bondholders, and the bond stops paying interest. A ten-year bond issued in 2026 might mature in 2036.","The time remaining until maturity strongly affects a bond\'s behaviour. Bonds with longer maturities usually pay higher interest, because investors want compensation for tying up money longer and for greater uncertainty. They are also more sensitive to interest rate changes: their prices move more when rates rise or fall.","Some bonds can be repaid before their maturity date. A callable bond allows the issuer to repay early, often when interest rates have fallen. A puttable bond allows the investor to demand early repayment.","The term is also used for other contracts. A certificate of deposit matures when the deposit term ends, and a loan matures when the final payment is due. In derivatives, the date a contract ends is usually called the expiration date, although maturity date is sometimes used for contracts such as futures and swaps."],"note":"","total":1500,"prev":{"slug":"materiality","term":"Materiality"},"next":{"slug":"maximum-drawdown","term":"Maximum Drawdown"}}')}}]);